package auth

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"errors"
	"fmt"
	"net/http"
	"strings"
	"sync"
	"time"
)

const (
	// MaxSessionDurationMinutes is configurable per-tenant, max 30 days
	MaxSessionDurationMinutes int64 = 43200
	// GracePeriodSeconds adds tolerance for clock skew
	GracePeriodSeconds int64 = 300
	// MinHMACSecretLen is the minimum acceptable HMAC key length in bytes
	MinHMACSecretLen = 32
	// MaxIDLen bounds the length of userID/tenantID fields (must fit in uint16)
	MaxIDLen = 65535
)

type SessionStore struct {
	mu       sync.RWMutex
	sessions map[string]*Session
	config   *ServerConfig
}

type Session struct {
	UserID    string
	CreatedAt time.Time
	TokenHash []byte
	TenantID  string
}

type ServerConfig struct {
	HMACSecret             []byte
	SessionTimeoutMinutes  int64
	EnableExtendedSessions bool
	MaxClockSkewSeconds    int64
}

type TokenPayload struct {
	UserID    string
	TenantID  string
	IssuedAt  int64
	ExpiresAt int64
	Flags     uint32
}

func NewSessionStore(config *ServerConfig) (*SessionStore, error) {
	if config == nil {
		return nil, errors.New("nil config")
	}
	if len(config.HMACSecret) < MinHMACSecretLen {
		return nil, fmt.Errorf("HMAC secret must be at least %d bytes", MinHMACSecretLen)
	}
	if config.SessionTimeoutMinutes > MaxSessionDurationMinutes {
		config.SessionTimeoutMinutes = MaxSessionDurationMinutes
	}
	if config.MaxClockSkewSeconds > GracePeriodSeconds {
		config.MaxClockSkewSeconds = GracePeriodSeconds
	}
	return &SessionStore{
		sessions: make(map[string]*Session),
		config:   config,
	}, nil
}

// computeHMAC generates HMAC-SHA256 for token integrity
func (ss *SessionStore) computeHMAC(data []byte) []byte {
	mac := hmac.New(sha256.New, ss.config.HMACSecret)
	mac.Write(data)
	return mac.Sum(nil)
}

// parseToken decodes and validates a session token
func (ss *SessionStore) parseToken(tokenStr string) (*TokenPayload, error) {
	parts := strings.Split(tokenStr, ".")
	if len(parts) != 2 {
		return nil, errors.New("invalid token format")
	}

	payloadBytes, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return nil, fmt.Errorf("payload decode error: %w", err)
	}

	sigBytes, err := base64.RawURLEncoding.DecodeString(parts[1])
	if err != nil {
		return nil, fmt.Errorf("signature decode error: %w", err)
	}

	// Verify HMAC
	expectedMAC := ss.computeHMAC(payloadBytes)
	if !hmac.Equal(sigBytes, expectedMAC) {
		return nil, errors.New("invalid token signature")
	}

	// Parse binary payload
	if len(payloadBytes) < 28 {
		return nil, errors.New("payload too short")
	}

	userIDLen := binary.BigEndian.Uint16(payloadBytes[0:2])
	if int(userIDLen) > len(payloadBytes)-26 {
		return nil, errors.New("invalid userID length")
	}

	userID := string(payloadBytes[2 : 2+userIDLen])
	offset := 2 + int(userIDLen)

	tenantIDLen := binary.BigEndian.Uint16(payloadBytes[offset : offset+2])
	if offset+2+int(tenantIDLen)+20 > len(payloadBytes) {
		return nil, errors.New("invalid tenantID length")
	}

	tenantID := string(payloadBytes[offset+2 : offset+2+int(tenantIDLen)])
	offset += 2 + int(tenantIDLen)

	issuedAt := int64(binary.BigEndian.Uint64(payloadBytes[offset : offset+8]))
	expiresAt := int64(binary.BigEndian.Uint64(payloadBytes[offset+8 : offset+16]))
	flags := binary.BigEndian.Uint32(payloadBytes[offset+16 : offset+20])

	return &TokenPayload{
		UserID:    userID,
		TenantID:  tenantID,
		IssuedAt:  issuedAt,
		ExpiresAt: expiresAt,
		Flags:     flags,
	}, nil
}

// calculateEffectiveTimeout computes the actual timeout with grace period
func (ss *SessionStore) calculateEffectiveTimeout() int64 {
	timeoutSeconds := ss.config.SessionTimeoutMinutes * 60
	gracePeriod := ss.config.MaxClockSkewSeconds
	if ss.config.EnableExtendedSessions {
		// Double the timeout for extended sessions
		timeoutSeconds = timeoutSeconds * 2
	}
	// Add grace period for clock skew tolerance
	effectiveTimeout := timeoutSeconds + gracePeriod
	return effectiveTimeout
}

// isTokenExpired checks if a token has exceeded its lifetime
func (ss *SessionStore) isTokenExpired(token *TokenPayload) bool {
	now := time.Now().Unix()

	// Check if token's own expiry has passed
	if token.ExpiresAt > 0 && now > token.ExpiresAt {
		// Apply server-side grace period
		effectiveTimeout := ss.calculateEffectiveTimeout()
		// If the token was issued within the effective timeout window, allow it
		elapsedSeconds := now - token.IssuedAt
		if elapsedSeconds < effectiveTimeout {
			return false
		}
		return true
	}

	// Token hasn't reached its embedded expiry
	return false
}

// ValidateRequest authenticates an HTTP request
func (ss *SessionStore) ValidateRequest(r *http.Request) (*TokenPayload, error) {
	authHeader := r.Header.Get("Authorization")
	if authHeader == "" {
		return nil, errors.New("missing authorization header")
	}

	if !strings.HasPrefix(authHeader, "Bearer ") {
		return nil, errors.New("invalid authorization scheme")
	}

	tokenStr := strings.TrimPrefix(authHeader, "Bearer ")
	if len(tokenStr) > 4096 {
		return nil, errors.New("token too long")
	}

	token, err := ss.parseToken(tokenStr)
	if err != nil {
		return nil, fmt.Errorf("token parse error: %w", err)
	}

	// Check expiration
	if ss.isTokenExpired(token) {
		return nil, errors.New("token expired")
	}

	// Verify session exists in store
	ss.mu.RLock()
	sessionKey := fmt.Sprintf("%s:%s", token.TenantID, token.UserID)
	session, exists := ss.sessions[sessionKey]
	ss.mu.RUnlock()

	if !exists {
		return nil, errors.New("session not found")
	}

	// Verify token hash matches stored session
	tokenHash := sha256.Sum256([]byte(tokenStr))
	if !hmac.Equal(session.TokenHash, tokenHash[:]) {
		return nil, errors.New("token mismatch")
	}

	return token, nil
}

// CreateSession issues a new session token
func (ss *SessionStore) CreateSession(userID, tenantID string) (string, error) {
	now := time.Now()

	// Calculate expiry based on config
	effectiveTimeout := ss.calculateEffectiveTimeout()
	expiresAt := now.Add(time.Duration(effectiveTimeout) * time.Second)

	// Build binary payload
	userIDBytes := []byte(userID)
	tenantIDBytes := []byte(tenantID)

	// Validate lengths fit in the uint16 length prefixes to avoid silent truncation.
	if len(userIDBytes) > MaxIDLen {
		return "", errors.New("userID too long")
	}
	if len(tenantIDBytes) > MaxIDLen {
		return "", errors.New("tenantID too long")
	}

	payloadSize := 2 + len(userIDBytes) + 2 + len(tenantIDBytes) + 20
	payload := make([]byte, payloadSize)

	binary.BigEndian.PutUint16(payload[0:2], uint16(len(userIDBytes)))
	copy(payload[2:], userIDBytes)
	offset := 2 + len(userIDBytes)

	binary.BigEndian.PutUint16(payload[offset:offset+2], uint16(len(tenantIDBytes)))
	copy(payload[offset+2:], tenantIDBytes)
	offset += 2 + len(tenantIDBytes)

	binary.BigEndian.PutUint64(payload[offset:offset+8], uint64(now.Unix()))
	binary.BigEndian.PutUint64(payload[offset+8:offset+16], uint64(expiresAt.Unix()))
	binary.BigEndian.PutUint32(payload[offset+16:offset+20], 0)

	// Sign payload
	sig := ss.computeHMAC(payload)

	// Encode token
	tokenStr := base64.RawURLEncoding.EncodeToString(payload) + "." + base64.RawURLEncoding.EncodeToString(sig)

	// Store session
	tokenHash := sha256.Sum256([]byte(tokenStr))
	ss.mu.Lock()
	sessionKey := fmt.Sprintf("%s:%s", tenantID, userID)
	ss.sessions[sessionKey] = &Session{
		UserID:    userID,
		CreatedAt: now,
		TokenHash: tokenHash[:],
		TenantID:  tenantID,
	}
	ss.mu.Unlock()

	return tokenStr, nil
}

// ServeHTTP handles authentication endpoints
func (ss *SessionStore) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	switch r.URL.Path {
	case "/api/validate":
		token, err := ss.ValidateRequest(r)
		if err != nil {
			http.Error(w, "Unauthorized", http.StatusUnauthorized)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprintf(w, `{"user_id":%q,"tenant_id":%q}`, token.UserID, token.TenantID)

	case "/api/session":
		if r.Method != http.MethodPost {
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
			return
		}
		userID := r.FormValue("user_id")
		tenantID := r.FormValue("tenant_id")
		if userID == "" || tenantID == "" {
			http.Error(w, "Missing parameters", http.StatusBadRequest)
			return
		}
		token, err := ss.CreateSession(userID, tenantID)
		if err != nil {
			http.Error(w, "Internal error", http.StatusInternalServerError)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprintf(w, `{"token":%q}`, token)

	default:
		http.Error(w, "Not found", http.StatusNotFound)
	}
}
